-- Generated by build-assessment-support-04-20.mjs; reviewed support content only.
-- Active v4 question IDs/keys/options and existing attempt snapshots remain unchanged.
-- Unexpected edits to a targeted field require review; unrelated owner edits are preserved.
CREATE TABLE IF NOT EXISTS n5_assessment_support_backup_185 (
  lesson_id uuid PRIMARY KEY, before_lesson jsonb NOT NULL,
  before_questions jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now()
);

DO $support$
DECLARE target uuid; matches int;
BEGIN
 SELECT count(*),(array_agg(l.id))[1] INTO matches,target
 FROM lessons l JOIN modules m ON m.id=l.module_id JOIN courses c ON c.id=m.course_id
 WHERE c.slug='n5' AND m.slug='n5-b4' AND l.type='quiz'
 AND l.slug LIKE 'assignment-bab-4-%';
 IF matches<>1 THEN RAISE EXCEPTION '185: missing/ambiguous Bab 4 assignment'; END IF;
 PERFORM 1 FROM lessons WHERE id=target FOR UPDATE;
 IF EXISTS(SELECT 1 FROM n5_assessment_support_backup_185 WHERE lesson_id=target) THEN RETURN; END IF;
 IF (SELECT assessment_policy->>'version' FROM lessons WHERE id=target) IS DISTINCT FROM 'n5-assessment-v4'
 THEN RAISE EXCEPTION '185: expected v4 Bab 4'; END IF;
 IF (SELECT count(*) FROM quiz_questions WHERE lesson_id=target AND assessment_meta->>'version'='n5-assessment-v4')<>24
 THEN RAISE EXCEPTION '185: expected 24 active questions Bab 4'; END IF;
 IF (SELECT (assessment_policy->'transferTask')-'exampleDialogue' FROM lessons WHERE id=target) IS DISTINCT FROM '{"prompt":"Latihan lisan opsional di luar nilai: gunakan informasi dari salah satu bacaan untuk menjelaskan situasi dengan pola bab ini.","rubric":["Informasi sesuai stimulus.","Pola yang dipelajari digunakan sesuai makna.","Jawaban singkat yang setara dan benar dapat diterima."]}'::jsonb
 THEN RAISE EXCEPTION '185: review owner transfer-task edit Bab 4 before applying'; END IF;
 INSERT INTO n5_assessment_support_backup_185(lesson_id,before_lesson,before_questions)
 SELECT l.id,to_jsonb(l),COALESCE((SELECT jsonb_agg(to_jsonb(q) || jsonb_build_object('options',
   (SELECT COALESCE(jsonb_agg(to_jsonb(o) ORDER BY o.sort_order,o.id),'[]'::jsonb) FROM quiz_options o WHERE o.question_id=q.id)) ORDER BY q.id)
   FROM quiz_questions q WHERE q.lesson_id=target AND false),'[]'::jsonb)
 FROM lessons l WHERE l.id=target;
 UPDATE lessons SET assessment_policy=jsonb_set(assessment_policy,'{transferTask}',(assessment_policy->'transferTask') || '{"title":"Mengenali benda dan mengoreksi dugaan","prompt":"Tulis 4–5 kalimat berdasarkan fakta pada kartu. Coba dahulu sebelum membuka contoh. Latihan ini tidak mengubah nilai kuis.","steps":["Baca kartu peran. Bedakan これ／それ／あれ dan この／その／あの sesuai posisi; gunakan の serta konfirmasi atau koreksi.","Tulis 4–5 kalimat yang menyampaikan fakta pada kartu. Utamakan pola bab ini; materi dari bab sebelumnya boleh digunakan.","Cocokkan tulisan dengan kartu dan rubrik. Setelah memeriksa contoh, perbaiki tulisan sendiri, lalu ganti satu fakta secara konsisten menggunakan kosakata yang sudah dipelajari."],"roleCards":[{"role":"A","name":"Anna","facts":"Anda memegang buku bahasa Jepang dan buku catatan milik sendiri. Hadi memegang payung milik Hadi. Tas milik Anna berada jauh dari kalian berdua."}],"exampleText":"これは にほんごの ほんです。この ノートは わたしのです。その かさは ハディさんのです。あの かばんは わたしのです。","rubric":["Informasi: sekurangnya tiga fakta disampaikan sesuai kartu; angka, waktu, orang, dan tempat tidak tertukar.","Tata bahasa: Bedakan これ／それ／あれ dan この／その／あの sesuai posisi; gunakan の serta konfirmasi atau koreksi.","Kelengkapan: tulisan terdiri dari 4–5 kalimat, menggunakan fokus bab, dan tidak bertentangan dengan fakta pada kartu.","Keterpahaman: tulisan dapat dibaca dan hubungan antarkalimat jelas. Kesalahan kecil yang tidak mengubah maksud masih diterima."],"rubricScale":["2 — Terpenuhi secara mandiri dan maknanya jelas.","1 — Sebagian terpenuhi; masih perlu petunjuk atau satu perbaikan.","0 — Belum terlihat atau maknanya berbeda dari yang diminta."],"acceptedVariations":"Jawaban tidak perlu sama persis dengan contoh. Subjek yang sudah jelas boleh tidak diulang. Nama dan angka boleh diganti secara konsisten setelah percobaan pertama. Posisi benda harus tetap jelas. Bentuk singkat わたしのです dapat diterima jika bendanya sudah disebut."}'::jsonb,true),updated_at=now() WHERE id=target;
END;
