 UPDATE lessons SET assessment_policy=jsonb_set(assessment_policy,'{transferTask}',(assessment_policy->'transferTask') || '{"title":"Menyepakati rencana bersama","prompt":"Tulis 4–5 kalimat berdasarkan fakta pada kartu. Coba dahulu sebelum membuka contoh. Latihan ini tidak mengubah nilai kuis.","steps":["Baca kartu peran. Bedakan keinginan, niat, rencana, dan ajakan; respons harus sesuai ketersediaan pada kartu.","Tulis 4–5 kalimat yang menyampaikan fakta pada kartu. Utamakan pola bab ini; materi dari bab sebelumnya boleh digunakan.","Cocokkan tulisan dengan kartu dan rubrik. Setelah memeriksa contoh, perbaiki tulisan sendiri, lalu ganti satu fakta secara konsisten menggunakan kosakata yang sudah dipelajari."],"roleCards":[{"role":"A","name":"Anna","facts":"Ingin menonton film besok. Berencana pergi ke kota. Ingin tas baru. Dapat bertemu besok pukul 14.00 di stasiun."}],"exampleText":"あした えいがを みたいです。まちへ いく つもりです。あたらしい かばんが ほしいです。ごご にじに えきで あう よていです。","rubric":["Informasi: sekurangnya tiga fakta disampaikan sesuai kartu; angka, waktu, orang, dan tempat tidak tertukar.","Tata bahasa: Bedakan keinginan, niat, rencana, dan ajakan; respons harus sesuai ketersediaan pada kartu.","Kelengkapan: tulisan terdiri dari 4–5 kalimat, menggunakan fokus bab, dan tidak bertentangan dengan fakta pada kartu.","Keterpahaman: tulisan dapat dibaca dan hubungan antarkalimat jelas. Kesalahan kecil yang tidak mengubah maksud masih diterima."],"rubricScale":["2 — Terpenuhi secara mandiri dan maknanya jelas.","1 — Sebagian terpenuhi; masih perlu petunjuk atau satu perbaikan.","0 — Belum terlihat atau maknanya berbeda dari yang diminta."],"acceptedVariations":"Jawaban tidak perlu sama persis dengan contoh. Subjek yang sudah jelas boleh tidak diulang. Nama dan angka boleh diganti secara konsisten setelah percobaan pertama. つもり dan よてい dapat sama-sama diterima jika sesuai maksud. Keduanya tidak perlu dipaksakan sebagai pilihan yang saling meniadakan."}'::jsonb,true),updated_at=now() WHERE id=target;
END;
$support$;

DO $support$
DECLARE target uuid; matches int;
BEGIN
 SELECT count(*),(array_agg(l.id))[1] INTO matches,target
 FROM lessons l JOIN modules m ON m.id=l.module_id JOIN courses c ON c.id=m.course_id
 WHERE c.slug='n5' AND m.slug='n5-b20' AND l.type='quiz'
 AND l.slug LIKE 'assignment-bab-20-%';
 IF matches<>1 THEN RAISE EXCEPTION '185: missing/ambiguous Bab 20 assignment'; END IF;
 PERFORM 1 FROM lessons WHERE id=target FOR UPDATE;
 IF EXISTS(SELECT 1 FROM n5_assessment_support_backup_185 WHERE lesson_id=target) THEN RETURN; END IF;
 IF (SELECT assessment_policy->>'version' FROM lessons WHERE id=target) IS DISTINCT FROM 'n5-assessment-v4'
 THEN RAISE EXCEPTION '185: expected v4 Bab 20'; END IF;
 IF (SELECT count(*) FROM quiz_questions WHERE lesson_id=target AND assessment_meta->>'version'='n5-assessment-v4')<>24
 THEN RAISE EXCEPTION '185: expected 24 active questions Bab 20'; END IF;
 IF (SELECT (assessment_policy->'transferTask')-'exampleDialogue' FROM lessons WHERE id=target) IS DISTINCT FROM '{"prompt":"Latihan lisan opsional di luar nilai: gunakan informasi dari salah satu bacaan untuk menjelaskan situasi dengan pola bab ini.","rubric":["Informasi sesuai stimulus.","Pola yang dipelajari digunakan sesuai makna.","Jawaban singkat yang setara dan benar dapat diterima."]}'::jsonb
 THEN RAISE EXCEPTION '185: review owner transfer-task edit Bab 20 before applying'; END IF;
 INSERT INTO n5_assessment_support_backup_185(lesson_id,before_lesson,before_questions)
 SELECT l.id,to_jsonb(l),COALESCE((SELECT jsonb_agg(to_jsonb(q) || jsonb_build_object('options',
   (SELECT COALESCE(jsonb_agg(to_jsonb(o) ORDER BY o.sort_order,o.id),'[]'::jsonb) FROM quiz_options o WHERE o.question_id=q.id)) ORDER BY q.id)
   FROM quiz_questions q WHERE q.lesson_id=target AND false),'[]'::jsonb)
 FROM lessons l WHERE l.id=target;
 UPDATE lessons SET assessment_policy=jsonb_set(assessment_policy,'{transferTask}',(assessment_policy->'transferTask') || '{"title":"Menceritakan pengalaman dan alasan","prompt":"Tulis 4–5 kalimat berdasarkan fakta pada kartu. Coba dahulu sebelum membuka contoh. Latihan ini tidak mengubah nilai kuis.","steps":["Baca kartu peran. Gunakan たことがあります untuk pengalaman, から untuk alasan, serta penghubung yang sesuai urutan atau pertentangan.","Tulis 4–5 kalimat yang menyampaikan fakta pada kartu. Utamakan pola bab ini; materi dari bab sebelumnya boleh digunakan.","Cocokkan tulisan dengan kartu dan rubrik. Setelah memeriksa contoh, perbaiki tulisan sendiri, lalu ganti satu fakta secara konsisten menggunakan kosakata yang sudah dipelajari."],"roleCards":[{"role":"A","name":"Anna","facts":"Tahun lalu pergi ke Jepang bersama teman. Pernah makan sushi, belum pernah natto. Hari berikutnya hujan sehingga tidak pergi ke taman; membaca buku di hotel. Ingin kembali tahun depan."}],"exampleText":"わたしは にほんへ いったことが あります。きょねん、ともだちと いきました。すしを たべました。でも、なっとうは たべたことが ありません。つぎの ひは あめでしたから、こうえんへ いきませんでした。","rubric":["Informasi: sekurangnya tiga fakta disampaikan sesuai kartu; angka, waktu, orang, dan tempat tidak tertukar.","Tata bahasa: Gunakan たことがあります untuk pengalaman, から untuk alasan, serta penghubung yang sesuai urutan atau pertentangan.","Kelengkapan: tulisan terdiri dari 4–5 kalimat, menggunakan fokus bab, dan tidak bertentangan dengan fakta pada kartu.","Keterpahaman: tulisan dapat dibaca dan hubungan antarkalimat jelas. Kesalahan kecil yang tidak mengubah maksud masih diterima."],"rubricScale":["2 — Terpenuhi secara mandiri dan maknanya jelas.","1 — Sebagian terpenuhi; masih perlu petunjuk atau satu perbaikan.","0 — Belum terlihat atau maknanya berbeda dari yang diminta."],"acceptedVariations":"Jawaban tidak perlu sama persis dengan contoh. Subjek yang sudah jelas boleh tidak diulang. Nama dan angka boleh diganti secara konsisten setelah percobaan pertama. Kejadian tertentu boleh memakai bentuk lampau biasa; pengalaman hidup memakai たことがあります. Variasi yang menjaga fakta dan hubungan sebab diterima."}'::jsonb,true),updated_at=now() WHERE id=target;
END;
$support$;
